command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $repo
& git fetch origin work/create-folder-shortcuts-20261005 --no-tags --prune
if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
& git worktree prune
$temp=Join-Path ([System.IO.Path]::GetTempPath()) "fly-create-folder-shortcuts-validation"
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp 9af6c368a15853e5aab96906f6a298e733f3c40c
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  Set-Location -LiteralPath $temp
  & git diff --check 6a2f42a8e2ef25dfe0af4d64256d2a042afe9fcf 9af6c368a15853e5aab96906f6a298e733f3c40c
  if($LASTEXITCODE -ne 0){throw "git diff check failed"}

  & python -X utf8 tools\winui\run_checks.py build --configuration Release
  $buildCode=$LASTEXITCODE
  if($buildCode -ne 0){throw "Release build failed with code $buildCode"}

  & python -X utf8 tools\winui\run_checks.py gui --configuration Release --area file-operations
  $guiCode=$LASTEXITCODE
  if($guiCode -ne 0){throw "file-operations GUI failed with code $guiCode"}

  Write-Host "CREATE_FOLDER_SHORTCUT_VALIDATION=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
